insert into public.reg_pack (id, version, published_at, notes) values
  ('oregon-2026-09-02', 1, '2026-09-02T12:00:00Z', 'Oregon ocean (ODFW): 2026 marine bottomfish table verbatim — general marine 4/day all depths year-round, canary 2 sub-bag, cabezon 1 (Jul–Dec, 16-inch), lingcod 3 (22-inch), sablefish 10, flatfish 25, offshore long-leader 10, halibut per the federal Area 2A catch-sharing plan. Yelloweye and quillback rockfish retention prohibited; descending device mandatory on boats. Salmon/shellfish not yet shipped.')
on conflict (id) do update set version = excluded.version, notes = excluded.notes;

