insert into public.reg_pack (id, version, published_at, notes) values
  ('washington-2026-09-02', 1, '2026-09-02T12:00:00Z', 'Washington ocean Marine Areas 1–4 (WDFW news release March 5, 2026): 2026 coastal bottomfish aggregate 9/day (≤7 rockfish, ≤5 canary; 2 lingcod; 1 cabezon; no min sizes), copper/quillback/vermilion possession prohibited May–July, yelloweye prohibited year-round, descending device mandatory on boats, surfperch 12 / shiner 15, halibut 1/day per the federal Area 2A plan. Marine Areas 5–13 (Puget Sound) and salmon/shellfish not yet shipped.')
